/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        propName: 'popoverParams',
        value: {
            "sysId": api.item.value.sys_id,
            "table": api.item.value.table
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        route: "record",
        fields: {
            table: api.state.popoverParams.table,
            sysId: api.state.popoverParams.sysId
        },
        params: null,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: "current",
        external: null,
        navigationOptions: null
    };
}
